-- Extend clock value validation without rewriting retained execution history.
-- Only the original writer can transfer a process clock owner; SQL values alone
-- remain correlation data. Stop/readback of historical executions is preserved.
LOCK TABLE occ.turn_journal_operations IN ACCESS EXCLUSIVE MODE;

