CREATE OR REPLACE FUNCTION occ.turn_journal_execution_valid(kind text,value jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,occ AS $$
DECLARE intent jsonb; start jsonb; execution jsonb; dispatch jsonb; duration numeric; anchor numeric;
BEGIN
  IF NOT (occ.turn_journal_phase_schema_matches(occ.turn_journal_execution_definition(kind),value)
    AND occ.turn_journal_phase_intrinsic(value) AND octet_length(value::text)<=65536) IS TRUE THEN RETURN false; END IF;
  IF kind='executionInterruption' THEN start:=value->'start'; intent:=start->'intent';
  ELSIF kind='executionStart' THEN start:=value; intent:=value->'intent';
  ELSIF kind='executionIntent' THEN intent:=value;
  ELSIF kind='selectedExecution' THEN execution:=value;
  ELSE RETURN false; END IF;
  IF intent IS NOT NULL THEN execution:=intent->'execution'; dispatch:=intent->'dispatchClock';
    duration:=(intent->>'maximumExecutionMs')::numeric;
    anchor:=CASE WHEN dispatch->>'kind'='pre-commit-monotonic-v1' THEN (dispatch->>'anchorAtMs')::numeric ELSE (dispatch->>'committedAtMs')::numeric END;
    IF (dispatch->>'deadlineAtMs')::numeric<=anchor
      OR (dispatch->>'deadlineAtMs')::numeric-anchor>900000
      OR (dispatch->>'kind'='pre-commit-monotonic-v1' AND (dispatch->>'deadlineAtMs')::numeric-anchor<>900000) THEN RETURN false; END IF;
  END IF;
  IF execution->'attempt' IS DISTINCT FROM execution#>'{consumption,attempt}' THEN RETURN false; END IF;
  IF start IS NOT NULL THEN
    IF (start->>'startedAtMs')::numeric+duration>9007199254740991
      OR (start->>'deadlineAtMs')::numeric<=(start->>'startedAtMs')::numeric
      OR (start->>'deadlineAtMs')::numeric<>least((start->>'dispatchDeadlineAtMs')::numeric,(start->>'startedAtMs')::numeric+duration)
      OR (start->'clockSourceRef'=dispatch->'clockSourceRef' AND start->'clockEpochRef'=dispatch->'clockEpochRef'
        AND (start->'dispatchDeadlineAtMs' IS DISTINCT FROM dispatch->'deadlineAtMs' OR (start->>'startedAtMs')::numeric<anchor)) THEN RETURN false; END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END;
$$;

-- Closed historical decoding is not permission to create a new legacy intent
-- or start. Original immutable records and independently authorized interruption
-- retain their existing validation and lifetime.
CREATE FUNCTION occ.turn_journal_execution_clock_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,occ AS $$
DECLARE clock jsonb;
BEGIN
  clock:=CASE NEW.operation_kind WHEN 'execution-intent' THEN NEW.request->'dispatchClock'
    ELSE NEW.request#>'{intent,dispatchClock}' END;
  IF clock->>'kind' IS DISTINCT FROM 'pre-commit-monotonic-v1' THEN
    RAISE EXCEPTION 'Unsupported active dispatch clock' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION occ.turn_journal_execution_clock_guard() FROM PUBLIC;
CREATE TRIGGER turn_journal_execution_clock_guard BEFORE INSERT ON occ.turn_journal_operations
  FOR EACH ROW WHEN (NEW.operation_kind IN ('execution-intent','execution-start'))
  EXECUTE FUNCTION occ.turn_journal_execution_clock_guard();
